function selectOpt4Symbol(idx) {
  window.tppOpt4CurrentIdx = idx;
  const data = window.tppOpt4Data[idx];
  if (!data) return;
  const isMy = (typeof lang !== 'undefined' ? lang : 'my') === 'my';
  
  const card = document.getElementById('opt4-hero-card');
  const img = document.getElementById('opt4-card-img');
  const icon = document.getElementById('opt4-card-icon');
  const pill = document.getElementById('opt4-card-pill');
  const headline = document.getElementById('opt4-card-headline');
  const scripture = document.getElementById('opt4-card-scripture');
  const quote = document.getElementById('opt4-card-quote');

  if (card) {
    card.classList.add('flipping');
    setTimeout(() => {
      if (img) img.src = data.img;
      if (icon) icon.textContent = data.icon;
      if (pill) pill.textContent = data.tag;
      if (headline) headline.textContent = isMy ? data.titleMy : data.titleEn;
      if (scripture) scripture.textContent = isMy ? data.scriptureMy : data.scriptureEn;
      if (quote) quote.textContent = isMy ? data.quoteMy : data.quoteEn;
      card.classList.remove('flipping');
    }, 180);
  }

  document.querySelectorAll('.opt4-idea-btn').forEach((btn, i) => {
    btn.classList.toggle('active', i === idx);
  });
}
window.selectOpt4Symbol = selectOpt4Symbol;


function renderWindingEpisodesPath() {
  const container = document.getElementById('episodes-path-container');
  if (!container) return;

  const completed = getCompletedModules();
  const isMy = (typeof lang !== 'undefined' ? lang : 'en') === 'my';

  // Episodes 1-4 as linear path with exact text matching mockup photo
  const linearMods = MODULES.slice(0, 4);
  let html = linearMods.map(m => {
    const isDone = completed.includes(m.id) || m.id <= 2;
    const isCurrent = m.id === 3;
    const isInProgress = m.id === 4;

    let markerHtml = '';
    if (isDone) {
      markerHtml = '<div class="path-node-marker completed">✓</div>';
    } else if (isCurrent) {
      markerHtml = '<div class="path-node-marker current">●</div>';
    } else if (isInProgress) {
      markerHtml = '<div class="path-node-marker in-progress">▶</div>';
    } else {
      markerHtml = '<div class="path-node-marker locked">🔒</div>';
    }

    let badgeHtml = '';
    let rightActionHtml = '';
    let customTitle = m.title;

    if (m.id === 1) {
      customTitle = isMy ? 'အပြုအမူများကို နားလည်ခြင်း' : 'Understanding Behavior';
      badgeHtml = '<span class="path-badge-completed">Completed</span>';
      rightActionHtml = `<img src="${getVideoThumbSrc(m)}" alt="${customTitle}" class="path-card-thumb"/>`;
    } else if (m.id === 2) {
      customTitle = isMy ? 'အပြုသဘောဆောင်သော ဆက်သွယ်ပြောဆိုမှု' : 'Positive Communication';
      badgeHtml = '<span class="path-badge-completed">Completed</span>';
      rightActionHtml = `<img src="${getVideoThumbSrc(m)}" alt="${customTitle}" class="path-card-thumb"/>`;
    } else if (m.id === 3) {
      customTitle = isMy ? 'ဒေါသကို တည်ငြိမ်စွာ ကိုင်တွယ်ခြင်း' : 'Handling Tantrums Calmly';
      badgeHtml = `<span class="path-badge-current">Current</span> <span style="font-size:0.68rem;color:#ffffff;margin-left:4px;">12 min</span>`;
      rightActionHtml = '<div class="path-play-btn-circle">▶</div>';
    } else if (m.id === 4) {
      customTitle = isMy ? 'တက်ကြွစွာ နားထောင်ခြင်း၏ စွမ်းအား' : 'Power of Active Listening';
      badgeHtml = `
        <span class="path-badge-inprogress">In Progress</span>
        <div style="width:100%;height:4px;background:rgba(184,93,67,0.15);border-radius:2px;margin-top:6px;overflow:hidden;">
          <div style="width:65%;height:100%;background:linear-gradient(90deg,#e9a651,#b85d43);border-radius:2px;"></div>
        </div>
      `;
      rightActionHtml = '';
    }

    return `
      <div class="path-node-item">
        ${markerHtml}
        <div class="path-node-card ${isCurrent ? 'current' : ''}" onclick="selectMobileModuleVideo(${m.id}, true); switchAppTab('cinema');">
          <div class="path-card-info">
            <div class="path-card-title">${String(m.id).padStart(2, '0')}: ${customTitle}</div>
            <div class="path-card-badges" style="${isInProgress ? 'flex-direction:column;align-items:flex-start;' : ''}">${badgeHtml}</div>
          </div>
          ${rightActionHtml}
        </div>
      </div>
    `;
  }).join('');

  // Branching Milestones Grid for Episodes 5 to 8 (Exact match to Photo 3)
  const branchMods = [
    { id: 5, en: 'Bedtime Routines', my: 'အိပ်ရာဝင် အလေ့အထများ', badge: 'Next', badgeCls: 'path-badge-inprogress', icon: '🔓' },
    { id: 6, en: 'Setting Healthy Boundaries', my: 'ကျန်းမာသော စည်းကမ်းများ', badge: 'Locked', badgeCls: 'path-badge-locked', icon: '🔒' },
    { id: 7, en: 'Managing Big Emotions', my: 'ကြီးမားသော စိတ်လှုပ်ရှားမှုများ', badge: 'Locked', badgeCls: 'path-badge-locked', icon: '🔒' },
    { id: 8, en: 'Connection Play', my: 'ရင်းနှီးမှု တည်ဆောက်သော ကစားနည်း', badge: 'Locked', badgeCls: 'path-badge-locked', icon: '🔒' }
  ];

  html += `
    <div style="margin-top:14px;padding-left:0;">
      <div class="path-branch-grid">
        ${branchMods.map(b => `
          <div class="path-branch-card" onclick="selectMobileModuleVideo(${b.id}, true); switchAppTab('cinema');">
            <div class="path-branch-title">Episode ${String(b.id).padStart(2, '0')}:<br>${isMy ? b.my : b.en}</div>
            <div class="path-branch-badge-row">
              <span class="${b.badgeCls}">${b.badge}</span>
              <span style="font-size:0.8rem;">${b.icon}</span>
            </div>
          </div>
        `).join('')}
      </div>
    </div>
  `;

  container.innerHTML = html;
}


function initMobileCinema() {
  renderMobileModuleChips();
  selectMobileModuleVideo(currentMobileModId, false);
  updateMobileProgressUI();

  // Keep simplified Play button in sync with HTML5 video events
  const vid = document.getElementById('mobile-cinema-video');
  if (vid && !vid._listenersBound) {
    vid._listenersBound = true;
    vid.addEventListener('play', () => {
      const isMy = (typeof lang !== 'undefined' ? lang : 'en') === 'my';
      const lbl = document.getElementById('ctrl-lbl-play');
      const ico = document.getElementById('cinema-ctrl-icon-play');
      if (lbl) lbl.textContent = isMy ? 'ခေတ္တရပ်ရန်' : 'Pause';
      if (ico) ico.textContent = '⏸';
    });
    vid.addEventListener('pause', () => {
      const isMy = (typeof lang !== 'undefined' ? lang : 'en') === 'my';
      const lbl = document.getElementById('ctrl-lbl-play');
      const ico = document.getElementById('cinema-ctrl-icon-play');
      if (lbl) lbl.textContent = isMy ? 'ဖွင့်ရန်' : 'Play';
      if (ico) ico.textContent = '▶';
    });
    vid.addEventListener('ended', () => {
      const isMy = (typeof lang !== 'undefined' ? lang : 'en') === 'my';
      const lbl = document.getElementById('ctrl-lbl-play');
      const ico = document.getElementById('cinema-ctrl-icon-play');
      if (lbl) lbl.textContent = isMy ? 'ဖွင့်ရန်' : 'Play';
      if (ico) ico.textContent = '▶';
    });
  }
}

function renderMobileModuleChips() {
  const container = document.getElementById('mobile-modules-scroll');
  if (!container) return;

  const completed = getCompletedModules();
  const isMy = lang === 'my';

  container.innerHTML = MODULES.map(m => {
    const isAct = m.id === currentMobileModId;
    const isDone = completed.includes(m.id);
    const title = isMy ? m.myTitle : m.title;

    return `
      <div class="mobile-module-chip ${isAct ? 'active' : ''}" onclick="selectMobileModuleVideo(${m.id}, true)">
        <div class="mobile-chip-top">
          <span class="mobile-chip-badge">${m.icon} M${m.id}</span>
          <span class="mobile-chip-status">${isDone ? '✅' : '⏳'}</span>
        </div>
        <div class="mobile-chip-title">${title}</div>
        <div style="font-size:0.65rem;color:rgba(255,255,255,0.6);margin-top:3px">${m.dur} mins</div>
      </div>
    `;
  }).join('');
}

function selectMobileModuleVideo(modId, autoPlay = true) {
  currentMobileModId = modId;
  const mod = MODULES.find(m => m.id === modId);
  if (!mod) return;

  const isMy = (typeof lang !== 'undefined' ? lang : 'en') === 'my';
  const modTitle = isMy ? (mod.myTitle || mod.title) : mod.title;

  // Use offline-aware playback
  if (autoPlay) {
    playOfflineOrOnline(modId);
  } else {
    const iframe = document.getElementById('mobile-cinema-iframe');
    const video = document.getElementById('mobile-cinema-video');
    const isFile = mod.videoType === 'file' || (!mod.youtube && mod.fileUrl);
    if (isFile) {
      if (iframe) { iframe.style.display = 'none'; iframe.src = ''; }
      if (video) {
        video.style.display = 'block';
        video.poster = getVideoThumbSrc(mod);
        video.src = mod.fileUrl;
      }
      showOfflineBadge(false);
    } else {
      if (video) { video.pause(); video.src = ''; video.style.display = 'none'; }
      if (iframe) { iframe.style.display = 'block'; iframe.src = `https://www.youtube.com/embed/${mod.youtube}?rel=0&enablejsapi=1`; }
      showOfflineBadge(false);
    }
  }

  // Update Top Bar & Headings (Matching Photo 2)
  let displayTitle = modTitle;
  let displayDur = mod.dur || 15;
  // Respect exact title and duration from curriculum
  displayTitle = isMy ? (mod.myTitle || mod.title) : mod.title;
  displayDur = mod.dur || 15;

  const epNum = String(mod.id).padStart(2, '0');
  const currentTitleEl = document.getElementById('mobile-cinema-current-title');
  if (currentTitleEl) currentTitleEl.textContent = `🎙️ EP ${epNum}: ${displayTitle}`;

  const headingEl = document.getElementById('cinema-heading-title');
  if (headingEl) headingEl.textContent = `🎙️ Episode ${mod.id}: ${displayTitle} (${displayDur} min)`;

  const quoteSpotlightEl = document.getElementById('cinema-meta-quote');
  if (quoteSpotlightEl) {
    quoteSpotlightEl.textContent = isMy ? `«${mod.mySub || mod.sub}»` : `“${mod.sub || mod.mySub}”`;
  }
  const scriptureSpotlightEl = document.getElementById('cinema-meta-scripture');
  if (scriptureSpotlightEl) {
    scriptureSpotlightEl.textContent = `📖 ${isMy ? (mod.myScripture || mod.scripture) : mod.scripture}`;
  }

  const hudTimeEl = document.getElementById('cinema-hud-time');
  if (hudTimeEl) hudTimeEl.textContent = `04:12 / ${displayDur}:30`;

  // Update 3 Stacked Takeaways (Matching Photo 2)
  const defaultTriplet = [
    { icon: '🧘', en: 'Stay grounded', my: 'ကိုယ်တိုင် တည်ငြိမ်မှု အရင်ယူပါ' },
    { icon: '🤗', en: 'Name their feeling', my: 'ကလေး၏ ခံစားချက်ကို နာမည်တပ် နားလည်ပေးပါ' },
    { icon: '🤝', en: 'Connect before correcting', my: 'မဆုံးမမီ မေတ္တာဖြင့် အရင်ဆက်သွယ်ပါ' }
  ];
  const list = TAKEAWAYS_MAP[mod.id] || defaultTriplet;

  for (let i = 1; i <= 3; i++) {
    const cardEl = document.getElementById(`takeaway-card-${i}`);
    const textEl = document.getElementById(`takeaway-text-${i}`);
    const item = list[i - 1] || defaultTriplet[i - 1];
    if (textEl && item) {
      textEl.textContent = isMy ? item.my : item.en;
    }
    if (cardEl && item) {
      const iconSpan = cardEl.querySelector('.takeaway-icon');
      if (iconSpan) iconSpan.textContent = item.icon;
    }
  }

  // Update Resources PDF Tip Sheet Card
  const resSheetTitle = document.getElementById('res-sheet-title');
  if (resSheetTitle) resSheetTitle.textContent = `Downloadable PDF Tip Sheet (Episode ${mod.id})`;

  // Update Favorite State
  try {
    const favs = JSON.parse(localStorage.getItem('tpp_favorites') || '[]');
    const isFav = favs.includes(mod.id);
    const favBtn = document.getElementById('cinema-btn-fav');
    if (favBtn) {
      favBtn.classList.toggle('active', isFav);
      favBtn.innerHTML = isFav
        ? '<svg viewBox="0 0 24 24" fill="currentColor" width="22" height="22"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>'
        : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="22" height="22"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>';
    }
  } catch(e) {}

  // Update Simplified 2-Button Capsule: Play and Save State
  try {
    const bms = JSON.parse(localStorage.getItem('tpp_bookmarks') || '[]');
    const isSaved = bms.includes(mod.id);
    const saveBtn = document.getElementById('cinema-ctrl-save');
    const saveLbl = document.getElementById('ctrl-lbl-save');
    const saveIco = document.getElementById('ctrl-ico-bookmark');
    if (saveBtn) saveBtn.classList.toggle('active', isSaved);
    if (saveLbl) saveLbl.textContent = isSaved ? (isMy ? 'သိမ်းပြီး' : 'Saved') : (isMy ? 'သိမ်းဆည်း' : 'Save');
    const _svgSave = '<svg viewBox="0 0 24 24" fill="currentColor" width="20" height="20"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg>';
    const _svgSaved = '<svg viewBox="0 0 24 24" fill="currentColor" width="20" height="20"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>';
    if (saveIco) saveIco.innerHTML = isSaved ? _svgSaved : _svgSave;
  } catch(e) {}

  const playLbl = document.getElementById('ctrl-lbl-play');
  const playIco = document.getElementById('cinema-ctrl-icon-play');
  if (playLbl) playLbl.textContent = autoPlay ? (isMy ? 'ခေတ္တရပ်ရန်' : 'Pause') : (isMy ? 'ဖွင့်ရန်' : 'Play');
  if (playIco) playIco.innerHTML = autoPlay
    ? '<svg viewBox="0 0 24 24" fill="currentColor" width="22" height="22"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>'
    : '<svg viewBox="0 0 24 24" fill="currentColor" width="22" height="22"><path d="M8 5v14l11-7z"/></svg>';

  // Update Completed Button
  const completed = getCompletedModules();
  const isDone = completed.includes(mod.id);
  const btnComp = document.getElementById('btn-toggle-mod-completed');
  const txtComp = document.getElementById('txt-mod-completed');
  const icoComp = document.getElementById('ico-mod-completed');
  if (btnComp) btnComp.classList.toggle('is-completed', isDone);
  if (txtComp) txtComp.textContent = isDone ? (isMy ? 'ပြီးဆုံးပြီ (Completed)' : 'Completed') : (isMy ? 'ပြီးဆုံးမှတ်သား (Mark Completed)' : 'Mark Completed');
  if (icoComp) icoComp.textContent = isDone ? '✅' : '✓';

  // Update Notes Pane Scripture & Action Step
  const badgeEl = document.getElementById('caption-card-badge');
  if (badgeEl) badgeEl.textContent = `📖 ${mod.scripture || ('Episode ' + mod.id)}`;
  const quoteMyEl = document.getElementById('caption-card-quote-my');
  if (quoteMyEl) quoteMyEl.textContent = `«${mod.mySub || mod.myTitle || ''}»`;
  const quoteEnEl = document.getElementById('caption-card-quote-en');
  if (quoteEnEl) quoteEnEl.textContent = `"${mod.sub || mod.title || ''}"`;
  const actionTextEl = document.getElementById('caption-card-action-text');
  if (actionTextEl) actionTextEl.textContent = isMy ? (mod.myAction || '') : (mod.action || '');

  // Load Saved Notes
  try {
    const notes = JSON.parse(localStorage.getItem('tpp_user_notes') || '{}');
    const area = document.getElementById('cinema-user-notes');
    if (area) area.value = notes[`mod_${mod.id}`] || '';
  } catch(e) {}

  refreshCurrentCinemaDownloadButton(mod.id);
}

function toggleModuleCompletedCurrent() {
  const completed = getCompletedModules();
  const idx = completed.indexOf(currentMobileModId);
  if (idx >= 0) {
    completed.splice(idx, 1);
    showToast(`မော်ဂျူး ${currentMobileModId} ကို မပြီးဆုံးသေးအဖြစ် ပြောင်းလိုက်ပါသည်`);
  } else {
    completed.push(currentMobileModId);
    playUpgradeChime();
    showToast(`🎉 မော်ဂျူး ${currentMobileModId} ပြီးဆုံးကြောင်း အောင်မြင်စွာ မှတ်သားပြီးပါပြီ!`);
    if (completed.length === 11) {
      setTimeout(() => {
        showToast('🏆 ဂုဏ်ယူပါသည်! မော်ဂျူး ၁၁ ခုစလုံး ပြီးဆုံးပါပြီ။ အောင်လက်မှတ်ကို ကြည့်ရှုနိုင်ပါပြီ!');
        openCertificateModal();
      }, 1000);
    }
  }
  saveCompletedModules(completed);
  selectMobileModuleVideo(currentMobileModId, false);
}

function openFeedbackForCurrentModule() {
  switchAppTab('prayer');
  switchPrayerFeedbackTab('feedback');
  const fbSelect = document.getElementById('fb-module-select');
  if (fbSelect) fbSelect.value = `Module ${currentMobileModId}`;
}

function openPrayerForCurrentModule() {
  switchAppTab('prayer');
  switchPrayerFeedbackTab('prayer');
  const catSelect = document.getElementById('prayer-cat');
  if (catSelect) catSelect.value = 'child';
}

// ==========================================
// PRAYER REQUESTS & COMMUNITY PRAYER WALL
// ==========================================
let livePrayers = [];

async function loadLivePrayers() {
  const container = document.getElementById('prayers-container');
  if (!container) return;

  try {
    const res = await fetch('/api/prayers');
    if (res.ok) {
      livePrayers = await res.json();
    }
  } catch (e) {
    console.log('Error loading prayers:', e);
  }

  if (!livePrayers || livePrayers.length === 0) {
    if (document.body.classList.contains('is-mobile-app')) {
      container.innerHTML = '';
      return;
    }
    container.innerHTML = `<div style="text-align:center;padding:1rem;color:rgba(255,255,255,0.6);font-size:0.8rem">ဆုတောင်းချက် မရှိသေးပါ။ သင်၏ မိသားစု ဆုတောင်းချက်ကို ပထမဆုံး စတင် တင်သွင်းနိုင်ပါသည် 🙏</div>`;
    return;
  }

  // In mobile app mode, do not render duplicate seed prayers (p-1, p-2, p-3) into prayers-container
  let displayPrayers = livePrayers;
  if (document.body.classList.contains('is-mobile-app')) {
    displayPrayers = livePrayers.filter(p => p.id && !p.id.toString().startsWith('p-') && p.id !== 'seed');
    if (displayPrayers.length === 0) {
      container.innerHTML = '';
      return;
    }
  }

  container.innerHTML = displayPrayers.map(p => {
    return `
      <div class="prayer-card" id="prayer-card-${p.id}">
        <div class="prayer-card-header">
          <span class="prayer-card-author">👤 ${p.author} <small style="font-weight:normal;color:rgba(255,255,255,0.6)">(${p.city})</small></span>
          <span class="prayer-card-cat">${p.catName || '🙏 ဆုတောင်းချက်'}</span>
        </div>
        <div class="prayer-card-text">${p.text}</div>
        <div class="prayer-card-footer">
          <span class="prayer-card-time">🕒 ${p.time}</span>
          <button type="button" class="prayer-btn-pray" onclick="incrementPrayer('${p.id}')">
            <span>🙏</span>
            <span id="pray-cnt-${p.id}">${p.prayerCount || 1}</span>
            <span>Parents Prayed</span>
          </button>
        </div>
      </div>
    `;
  }).join('');
}

async function handlePrayerSubmit(e) {
  e.preventDefault();
  const authorInput = document.getElementById('prayer-author');
  const cityInput = document.getElementById('prayer-city');
  const catInput = document.getElementById('prayer-cat');
  const textInput = document.getElementById('prayer-text');
  const btn = document.getElementById('btn-submit-prayer');

  if (!textInput || !textInput.value.trim()) return;

  const payload = {
    author: (authorInput ? authorInput.value.trim() : '') || 'မေမေ/ဖေဖေ',
    city: (cityInput ? cityInput.value.trim() : '') || 'မြန်မာ',
    cat: catInput ? catInput.value : 'family',
    catName: catInput ? catInput.options[catInput.selectedIndex].text : '👨‍👩‍👧‍👦 မိသားစု ဆုတောင်းချက်',
    text: textInput.value.trim()
  };

  if (btn) {
    btn.disabled = true;
    btn.textContent = 'တင်သွင်းနေပါသည်...';
  }

  try {
    const res = await fetch('/api/prayers', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    if (!res.ok) {
      sendToGoogleSheetsLive({
        type: 'prayer',
        author: payload.author,
        city: payload.city,
        category: payload.catName,
        text: payload.text
      });
    }
    if (res.ok) {
      textInput.value = '';
      playUpgradeChime();
      showToast('🙏 သင်၏ မိသားစု ဆုတောင်းလွှာကို အောင်မြင်စွာ တင်သွင်းပြီးပါပြီ!');
      await loadLivePrayers();
    } else {
      showToast('ဆုတောင်းလွှာ တင်သွင်းမှု မအောင်မြင်ပါ။ ပြန်လည်ကြိုးစားပါ');
    }
  } catch (err) {
    showToast('Network error: ' + err.message);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = '🙏 ဆုတောင်းလွှာ တင်သွင်းမည် (Submit Prayer)';
    }
  }
}

async function incrementPrayer(pId) {
  const cntEl = document.getElementById(`pray-cnt-${pId}`);
  if (cntEl) {
    let current = parseInt(cntEl.textContent, 10) || 0;
    cntEl.textContent = current + 1;
  }
  playUpgradeChime();
  if (navigator.vibrate) {
    try { navigator.vibrate(60); } catch(e) {}
  }
  showToast('❤️ ဆုတောင်းခြင်းတွင် ပါဝင်ပေးသည့်အတွက် ကျေးဇူးတင်ပါသည်!');

  try {
    await fetch('/api/prayers/pray', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: pId })
    });
  } catch (e) {}
}

// ==========================================
// MODULE FEEDBACK & TESTIMONIALS
// ==========================================
let liveFeedback = [];

function setFeedbackRating(stars) {
  currentFeedbackRating = stars;
  const starBtns = document.querySelectorAll('#fb-stars-row .star-btn');
  starBtns.forEach((btn, idx) => {
    btn.classList.toggle('active', idx < stars);
  });
}

async function loadLiveFeedback() {
  const container = document.getElementById('feedback-container');
  if (!container) return;

  try {
    const res = await fetch('/api/feedback');
    if (res.ok) {
      liveFeedback = await res.json();
    }
  } catch (e) {}

  if (!liveFeedback || liveFeedback.length === 0) {
    container.innerHTML = `<div style="text-align:center;padding:1rem;color:rgba(255,255,255,0.6);font-size:0.8rem">သုံးသပ်ချက် မရှိသေးပါ။ ပထမဆုံး စတင် ရေးသားနိုင်ပါသည် ⭐</div>`;
    return;
  }

  container.innerHTML = liveFeedback.map(fb => {
    const stars = '★'.repeat(fb.rating || 5) + '☆'.repeat(5 - (fb.rating || 5));
    return `
      <div class="prayer-card" style="border-left: 3px solid #ffcc00">
        <div class="prayer-card-header">
          <span class="prayer-card-author">👤 ${fb.author} <small style="color:#ffcc00">(${fb.church || 'မိတ်ဖက်မိဘ'})</small></span>
          <span style="color:#ffcc00;font-size:0.85rem">${stars}</span>
        </div>
        <div style="font-size:0.7rem;color:rgba(255,255,255,0.6);margin-bottom:4px">📚 ${fb.module}: ${fb.moduleTitle || ''}</div>
        <div class="prayer-card-text">${fb.text}</div>
        <div class="prayer-card-time">🕒 ${fb.time || '2026-09-24'}</div>
      </div>
    `;
  }).join('');
}

async function handleFeedbackSubmit(e) {
  e.preventDefault();
  const modSelect = document.getElementById('fb-module-select');
  const textInput = document.getElementById('fb-text');
  const btn = document.getElementById('btn-submit-fb');

  if (!textInput || !textInput.value.trim()) return;

  let session = null;
  try { session = JSON.parse(localStorage.getItem('tpp_user_session')); } catch(e) {}

  const payload = {
    module: modSelect ? modSelect.value : 'General',
    moduleTitle: modSelect ? modSelect.options[modSelect.selectedIndex].text : '',
    rating: currentFeedbackRating,
    text: textInput.value.trim(),
    author: (session && session.displayName) ? session.displayName : 'Parent',
    church: (session && session.churchName) ? session.churchName : 'Christian Family'
  };

  if (btn) {
    btn.disabled = true;
    btn.textContent = 'ပေးပို့နေပါသည်...';
  }

  try {
    const res = await fetch('/api/feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    if (!res.ok) {
      sendToGoogleSheetsLive({
        type: 'prayer',
        author: payload.author,
        city: payload.church,
        category: `⭐ ${payload.rating} Stars · ${payload.module}: ${payload.moduleTitle}`,
        text: payload.text
      });
    }
    if (res.ok) {
      textInput.value = '';
      playUpgradeChime();
      showToast('⭐ သင့်သုံးသပ်ချက်ကို အောင်မြင်စွာ လက်ခံရရှိပါပြီ။ ကျေးဇူးတင်ပါသည်!');
      await loadLiveFeedback();
    }
  } catch (err) {
    showToast('Network error: ' + err.message);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = '✍️ သုံးသပ်ချက် ပေးပို့မည် (Submit Feedback)';
    }
  }
}

function switchPrayerFeedbackTab(tab) {
  const btnP = document.getElementById('sec-tab-prayer');
  const btnF = document.getElementById('sec-tab-feedback');
  const viewP = document.getElementById('view-prayer-wall');
  const viewF = document.getElementById('view-feedback');

  if (btnP) btnP.classList.toggle('active', tab === 'prayer');
  if (btnF) btnF.classList.toggle('active', tab === 'feedback');

  if (viewP) viewP.style.display = tab === 'prayer' ? 'block' : 'none';
  if (viewF) viewF.style.display = tab === 'feedback' ? 'block' : 'none';

  if (tab === 'prayer') loadLivePrayers();
  if (tab === 'feedback') loadLiveFeedback();
}

// ==========================================
// IN-APP FAST LOGIN (NO REDIRECT NEEDED)
// ==========================================
function openInAppLoginModal(tab = 'signin') {
  const m = document.getElementById('inapp-login-modal');
  if (m) {
    m.classList.add('open');
    document.body.style.overflow = 'hidden';
    switchInAppAuthTab(tab);
  }
}

function closeInAppLoginModal() {
  const m = document.getElementById('inapp-login-modal');
  if (m) {
    m.classList.remove('open');
    document.body.style.overflow = '';
  }
}

function switchInAppAuthTab(tab) {
  const tabSignin = document.getElementById('tab-inapp-signin');
  const tabRegister = document.getElementById('tab-inapp-register');
  const formSignin = document.getElementById('inapp-login-form');
  const formRegister = document.getElementById('inapp-register-form');

  if (tab === 'register') {
    if (tabSignin) tabSignin.classList.remove('active');
    if (tabRegister) tabRegister.classList.add('active');
    if (formSignin) formSignin.style.display = 'none';
    if (formRegister) formRegister.style.display = 'block';
  } else {
    if (tabSignin) tabSignin.classList.add('active');
    if (tabRegister) tabRegister.classList.remove('active');
    if (formSignin) formSignin.style.display = 'block';
    if (formRegister) formRegister.style.display = 'none';
  }
}

function handleMobileUserClick() {
  let session = null;
  try { session = JSON.parse(localStorage.getItem('tpp_user_session')); } catch(e) {}
  if (session && session.loggedIn) {
    openSettingsModal();
  } else {
    openInAppLoginModal('signin');
  }
}

function updateMobileUserUI() {
  let session = null;
  try { session = JSON.parse(localStorage.getItem('tpp_user_session')); } catch(e) {}

  const btn = document.getElementById('mobile-app-btn-user');
  const ico = document.getElementById('mobile-user-icon');
  const lbl = document.getElementById('mobile-user-label');

  if (btn && lbl) {
    if (session && session.loggedIn) {
      btn.classList.add('is-logged-in');
      if (ico) ico.textContent = '👤';
      lbl.textContent = session.displayName ? session.displayName.split(' ')[0] : 'Member';
    } else {
      btn.classList.remove('is-logged-in');
      if (ico) ico.textContent = '🔑';
      lbl.textContent = 'Sign In';
    }
  }

  // Update Certificate info
  const certName = document.getElementById('cert-parent-name');
  const certChurch = document.getElementById('cert-church-name');
  if (certName && session && session.displayName) {
    certName.textContent = session.displayName;
  }
  if (certChurch && session && session.churchName) {
    certChurch.textContent = session.churchName;
  }
}

async function quickDemoLogin() {
  console.warn('[Security] 1-Tap Demo fast login has been deactivated for security compliance.');
  showToast('Please sign in with your registered church or school account.');
}

async function handleInAppLoginSubmit(e) {
  e.preventDefault();
  const emailInput = document.getElementById('inapp-email');
  const passInput = document.getElementById('inapp-password');
  const btn = document.getElementById('btn-inapp-login');

  const emailVal = emailInput ? emailInput.value.trim() : '';
  const passVal = passInput ? passInput.value.trim() : '';

  if (btn) {
    btn.disabled = true;
    btn.textContent = 'စစ်ဆေးနေပါသည်...';
  }

  try {
    const res = await fetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: emailVal, password: passVal })
    });
    const data = await res.json();
    if (res.ok && data.status === 'success') {
      const sessionData = {
        email: emailVal,
        displayName: data.displayName || 'Parent Facilitator',
        churchName: data.churchName || 'Partner Church',
        loggedIn: true,
        isGranted: true,
        role: data.role || 'facilitator',
        loginTime: new Date().toISOString()
      };
      localStorage.setItem('tpp_user_session', JSON.stringify(sessionData));
      userPrivilege.loggedIn = true;
      userPrivilege.isGranted = true;
      userPrivilege.displayName = sessionData.displayName;
      userPrivilege.churchName = sessionData.churchName;

      // Login record already synced cleanly via /api/login backend

      playUpgradeChime();
      showToast(`✓ မင်္ဂလာပါ ${sessionData.displayName}! မော်ဂျူးအားလုံး ကြည့်ရှုနိုင်ပါပြီ`);
      closeInAppLoginModal();
      updateMobileUserUI();
      updateSettingsModalUI();
      checkAuthStatus();
      initMobileCinema();
    } else {
      showToast('❌ ' + (data.error || 'အီးမေးလ် သို့မဟုတ် စကားဝှက် မှားယွင်းနေပါသည်'));
    }
  } catch (err) {
    showToast('⚠️ Network Error: ' + err.message);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = '🔑 အကောင့်ဝင်မည် (Sign In)';
    }
  }
}

async function handleInAppRegisterSubmit(e) {
  e.preventDefault();
  const churchInput = document.getElementById('inapp-reg-church');
  const regionInput = document.getElementById('inapp-reg-region');
  const cityInput = document.getElementById('inapp-reg-city');
  const coordInput = document.getElementById('inapp-reg-coord');
  const emailInput = document.getElementById('inapp-reg-email');
  const phoneInput = document.getElementById('inapp-reg-phone');
  const famInput = document.getElementById('inapp-reg-fam');
  const passInput = document.getElementById('inapp-reg-pass');
  const btn = document.getElementById('btn-inapp-reg');

  const churchVal = churchInput ? churchInput.value.trim() : '';
  const regionVal = regionInput ? regionInput.value : 'Yangon';
  const cityVal = cityInput ? cityInput.value.trim() : '';
  const coordVal = coordInput ? coordInput.value.trim() : '';
  const emailVal = emailInput ? emailInput.value.trim().toLowerCase() : '';
  const phoneVal = phoneInput ? phoneInput.value.trim() : '';
  const famVal = famInput ? famInput.value : '10–25 Families';
  const passVal = passInput ? passInput.value.trim() : '';

  if (!churchVal || !coordVal || !emailVal) {
    showToast('⚠️ ကျေးဇူးပြု၍ လိုအပ်သော အချက်အလက်များ ပြည့်စုံစွာ ဖြည့်စွက်ပါ');
    return;
  }

  if (btn) {
    btn.disabled = true;
    btn.textContent = 'မှတ်ပုံတင်နေပါသည်... (Saving to Sheet)';
  }

  const payload = {
    type: 'registration',
    source: 'Mobile App',
    churchName: churchVal,
    region: regionVal,
    city: cityVal,
    denom: 'Independent / Non-denominational',
    coordName: coordVal,
    email: emailVal,
    phone: phoneVal,
    fam: famVal,
    timestamp: new Date().toISOString()
  };

  payload.submissionId = 'reg_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);

  // Send to backend (backend syncs to Google Sheets once; fallback to client sync if offline)
  try {
    const res = await fetch('/api/register', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    if (!res.ok) {
      sendToGoogleSheetsLive(payload);
    }
  } catch (err) {
    console.warn('Backend offline, sending directly to Google Sheets:', err);
    sendToGoogleSheetsLive(payload);
  }

  // Immediately create user session and unlock all 11 modules
  const sessionData = {
    email: emailVal,
    displayName: coordVal,
    churchName: churchVal,
    loggedIn: true,
    isGranted: true,
    role: 'facilitator',
    loginTime: new Date().toISOString()
  };
  localStorage.setItem('tpp_user_session', JSON.stringify(sessionData));
  userPrivilege.loggedIn = true;
  userPrivilege.isGranted = true;
  userPrivilege.displayName = coordVal;
  userPrivilege.churchName = churchVal;

  playUpgradeChime();
  showToast(`🎉 မင်္ဂလာပါ ${coordVal}! အသင်းတော် စာရင်းသွင်းမှု အောင်မြင်ပြီး မော်ဂျူး ၁၁ ခုလုံး ဖွင့်လှစ်ပေးလိုက်ပါပြီ!`);

  // Close modal and update UI across the app
  closeInAppLoginModal();
  updateMobileUserUI();
  updateSettingsModalUI();
  checkAuthStatus();
  initMobileCinema();

  if (btn) {
    btn.disabled = false;
    btn.textContent = '📝 အခမဲ့ စာရင်းသွင်းမည် (Complete Registration)';
  }
}

