function closeDownloadOptionsSheet(e) {
  const overlay = document.getElementById('dl-options-sheet-overlay');
  if (!overlay) return;
  overlay.classList.remove('active');
  setTimeout(() => {
    overlay.style.display = 'none';
  }, 280);
}

function selectDownloadOptionQuality(quality) {
  _selectedSheetQuality = quality === 'hd' ? 'hd' : 'saver';

  const cardSaver = document.getElementById('dl-opt-card-saver');
  const cardHd = document.getElementById('dl-opt-card-hd');
  const radioSaver = document.getElementById('dl-opt-radio-saver');
  const radioHd = document.getElementById('dl-opt-radio-hd');
  const sizeEl = document.getElementById('dl-sheet-selected-size');

  if (cardSaver) cardSaver.classList.toggle('selected', _selectedSheetQuality === 'saver');
  if (cardHd) cardHd.classList.toggle('selected', _selectedSheetQuality === 'hd');

  if (radioSaver) radioSaver.classList.toggle('checked', _selectedSheetQuality === 'saver');
  if (radioHd) radioHd.classList.toggle('checked', _selectedSheetQuality === 'hd');

  if (sizeEl) {
    sizeEl.textContent = _selectedSheetQuality === 'hd' ? '~55 MB' : '~24 MB';
  }
}

function confirmStartDownloadFromSheet() {
  const modId = _currentSheetModId;
  const quality = _selectedSheetQuality;
  if (_rememberDownloadChoice) {
    localStorage.setItem('pp_remember_quality', quality);
    const isMy = (typeof lang !== 'undefined' ? lang : 'my') === 'my';
    showOfflineToast(isMy ? `💾 ${quality === 'hd' ? '720p HD' : '480p Data Saver'} ကို အမြဲတမ်းအသုံးပြုရန် သိမ်းဆည်းလိုက်ပါသည်` : `💾 Saved ${quality === 'hd' ? '720p HD' : '480p Data Saver'} as default quality`, 'success');
  }
  closeDownloadOptionsSheet();
  startVideoDownload(modId, quality);
}

function showDownloadFloatingCapsule(modId, pct, quality) {
  const capsule = document.getElementById('dl-floating-progress-capsule');
  if (!capsule) return;
  const isMy = (typeof lang !== 'undefined' ? lang : 'my') === 'my';
  const qLabel = quality === 'hd' ? '720p HD' : '480p Saver';
  const titleEl = document.getElementById('dl-capsule-title');
  const barEl = document.getElementById('dl-capsule-progress-fill');
  if (titleEl) {
    titleEl.textContent = isMy ? `📥 Episode ${modId} ဒေါင်းလုဒ် (${qLabel})... ${pct}%` : `📥 Downloading Episode ${modId} (${qLabel})... ${pct}%`;
  }
  if (barEl) {
    barEl.style.width = pct + '%';
  }
  capsule.style.display = 'flex';
}

function updateDownloadFloatingCapsule(modId, pct, loaded, total) {
  const titleEl = document.getElementById('dl-capsule-title');
  const barEl = document.getElementById('dl-capsule-progress-fill');
  const isMy = (typeof lang !== 'undefined' ? lang : 'my') === 'my';
  if (titleEl) {
    titleEl.textContent = isMy ? `📥 Episode ${modId} ဒေါင်းလုဒ် (${pct}%) · ${formatFileSize(loaded)} / ${formatFileSize(total)}` : `📥 Downloading Episode ${modId} (${pct}%) · ${formatFileSize(loaded)} / ${formatFileSize(total)}`;
  }
  if (barEl) {
    barEl.style.width = pct + '%';
  }
}

function hideDownloadFloatingCapsule(successMsg) {
  const capsule = document.getElementById('dl-floating-progress-capsule');
  if (!capsule) return;
  if (successMsg) {
    const titleEl = document.getElementById('dl-capsule-title');
    const barEl = document.getElementById('dl-capsule-progress-fill');
    if (titleEl) titleEl.textContent = successMsg;
    if (barEl) barEl.style.width = '100%';
    setTimeout(() => {
      capsule.style.display = 'none';
    }, 2800);
  } else {
    capsule.style.display = 'none';
  }
}

function cancelActiveDownloadFromCapsule() {
  if (_currentSheetModId && _activeDownloads[_currentSheetModId]) {
    cancelVideoDownload(_currentSheetModId);
  } else {
    const activeKeys = Object.keys(_activeDownloads);
    if (activeKeys.length > 0) {
      cancelVideoDownload(Number(activeKeys[0]));
    }
  }
  hideDownloadFloatingCapsule();
}

function updateCinemaDownloadButton(modId, state, pct) {
  const btn = document.getElementById('cinema-btn-download-cur');
  if (!btn || currentMobileModId !== modId) return;
  const isMy = (typeof lang !== 'undefined' ? lang : 'my') === 'my';
  btn.className = 'cinema-btn-dl-action ' + (state || '');
  if (state === 'downloading') {
    btn.innerHTML = `<span class="dl-capsule-icon-spinner" style="width:14px;height:14px;border-width:2px;display:inline-block"></span> <span>${pct}%</span>`;
    btn.onclick = () => cancelVideoDownload(modId);
    btn.title = 'Tap to cancel download';
  } else if (state === 'done') {
    btn.innerHTML = `<span>✓</span> <span>${isMy ? 'အော့ဖ်လိုင်း အသင့်ဖြစ်' : 'Saved Offline'}</span>`;
    btn.onclick = () => showOfflineToast(isMy ? '✅ ဒေါင်းလုဒ်ရယူပြီးဖြစ်ပါသည်' : '✅ Already downloaded!', 'success');
    btn.title = 'Available offline';
  } else {
    btn.innerHTML = `<span>📥</span> <span>${isMy ? 'ဒေါင်းလုဒ်' : 'Download'}</span>`;
    btn.onclick = () => openDownloadOptionsSheet(modId);
    btn.title = 'Download for offline';
  }
}

async function refreshCurrentCinemaDownloadButton(modId) {
  if (_activeDownloads[modId]) {
    updateCinemaDownloadButton(modId, 'downloading', _activeDownloads[modId].progress || 0);
  } else {
    const existing = await getOfflineVideo(modId);
    if (existing) {
      updateCinemaDownloadButton(modId, 'done', 100);
    } else {
      updateCinemaDownloadButton(modId, 'none', 0);
    }
  }
}

// Start download for a module with quality choice
async function startVideoDownload(modId, quality = 'saver') {
  const mod = MODULES.find(m => m.id === modId);
  if (!mod) return;
  const fileUrl = mod.fileUrl || `https://pub-9b38e79343f8404495945a9cf030a304.r2.dev/module-${modId}.mp4`;
  const isMy = (typeof lang !== 'undefined' ? lang : 'my') === 'my';

  if (_activeDownloads[modId]) {
    showOfflineToast(isMy ? '⏳ ဒေါင်းလုဒ် လုပ်ဆောင်နေဆဲဖြစ်ပါသည်...' : '⏳ Already downloading...', 'info');
    return;
  }
  const existing = await getOfflineVideo(modId);
  if (existing) {
    showOfflineToast(isMy ? '✅ စက်ထဲတွင် သိမ်းဆည်းပြီးဖြစ်ပါသည်!' : '✅ Already downloaded!', 'success');
    return;
  }

  showOfflineToast(isMy ? `📥 Episode ${modId} ဒေါင်းလုဒ် စတင်နေပါသည်...` : `📥 Starting download: Episode ${modId}...`, 'info');
  updateChipDownloadState(modId, 'downloading', 0);
  updateCinemaDownloadButton(modId, 'downloading', 0);
  showDownloadFloatingCapsule(modId, 0, quality);
  renderDownloadsPage();
  if (typeof renderNetflixDownloadsTab === 'function') renderNetflixDownloadsTab();
  if (typeof renderMcLibraryLessons === 'function') renderMcLibraryLessons();
    if (typeof renderHomePodcastReel === 'function') renderHomePodcastReel();

  const proxyUrl = getProxyUrl(fileUrl);
  const xhr = new XMLHttpRequest();
  _activeDownloads[modId] = { xhr, progress: 0, quality };

  xhr.open('GET', proxyUrl, true);
  xhr.responseType = 'blob';

  xhr.onprogress = e => {
    if (e.lengthComputable) {
      const pct = Math.round((e.loaded / e.total) * 100);
      _activeDownloads[modId].progress = pct;
      updateChipDownloadState(modId, 'downloading', pct);
      updateCinemaDownloadButton(modId, 'downloading', pct);
      updateDownloadFloatingCapsule(modId, pct, e.loaded, e.total);
      updateDownloadsPanelProgress(modId, pct, e.loaded, e.total);
      if (typeof updateNetflixLibraryProgress === 'function') updateNetflixLibraryProgress(modId, pct);
    }
  };

  xhr.onload = async () => {
    if (xhr.status === 200) {
      const blob = xhr.response;
      await saveOfflineVideo(modId, blob, {
        title: mod.title,
        myTitle: mod.myTitle,
        dur: mod.dur,
        size: blob.size,
        quality: quality || 'saver'
      });
      delete _activeDownloads[modId];
      updateChipDownloadState(modId, 'done', 100);
      updateCinemaDownloadButton(modId, 'done', 100);
      hideDownloadFloatingCapsule(isMy ? `✅ Episode ${modId} အော့ဖ်လိုင်းကြည့်ရန် အသင့်ဖြစ်ပါပြီ!` : `✅ Episode ${modId} saved offline!`);
      showOfflineToast(isMy ? `✅ Episode ${modId} အောင်မြင်စွာ သိမ်းဆည်းပြီးပါပြီ!` : `✅ Episode ${modId} saved for offline viewing!`, 'success');
      renderDownloadsPage();
      if (typeof renderNetflixDownloadsTab === 'function') renderNetflixDownloadsTab();
      if (typeof renderMcLibraryLessons === 'function') renderMcLibraryLessons();
    if (typeof renderHomePodcastReel === 'function') renderHomePodcastReel();
      // If this module is currently playing, switch to local blob
      if (currentMobileModId === modId) {
        playOfflineOrOnline(modId);
      }
    } else {
      delete _activeDownloads[modId];
      updateChipDownloadState(modId, 'none', 0);
      updateCinemaDownloadButton(modId, 'none', 0);
      hideDownloadFloatingCapsule();
      showOfflineToast(`❌ Download failed (${xhr.status}). Try again.`, 'error');
      renderDownloadsPage();
      if (typeof renderNetflixDownloadsTab === 'function') renderNetflixDownloadsTab();
      if (typeof renderMcLibraryLessons === 'function') renderMcLibraryLessons();
    if (typeof renderHomePodcastReel === 'function') renderHomePodcastReel();
    }
  };

  xhr.onerror = () => {
    delete _activeDownloads[modId];
    updateChipDownloadState(modId, 'none', 0);
    updateCinemaDownloadButton(modId, 'none', 0);
    hideDownloadFloatingCapsule();
    showOfflineToast(isMy ? '❌ ဒေါင်းလုဒ်မအောင်မြင်ပါ။ အင်တာနက်လိုင်း စစ်ဆေးပါ။' : '❌ Download failed. Check your connection.', 'error');
    renderDownloadsPage();
    if (typeof renderNetflixDownloadsTab === 'function') renderNetflixDownloadsTab();
    if (typeof renderMcLibraryLessons === 'function') renderMcLibraryLessons();
    if (typeof renderHomePodcastReel === 'function') renderHomePodcastReel();
  };

  xhr.send();
}

function cancelVideoDownload(modId) {
  if (_activeDownloads[modId]) {
    _activeDownloads[modId].xhr.abort();
    delete _activeDownloads[modId];
    updateChipDownloadState(modId, 'none', 0);
    updateCinemaDownloadButton(modId, 'none', 0);
    hideDownloadFloatingCapsule();
    showOfflineToast(`⏹ Download cancelled.`, 'info');
    renderDownloadsPage();
    if (typeof renderNetflixDownloadsTab === 'function') renderNetflixDownloadsTab();
    if (typeof renderMcLibraryLessons === 'function') renderMcLibraryLessons();
    if (typeof renderHomePodcastReel === 'function') renderHomePodcastReel();
  }
}

async function deleteOfflineAndRefresh(modId) {
  await deleteOfflineVideo(modId);
  updateChipDownloadState(modId, 'none', 0);
  updateCinemaDownloadButton(modId, 'none', 0);
  showOfflineToast(`🗑 Offline video deleted.`, 'info');
  renderDownloadsPage();
  if (typeof renderNetflixDownloadsTab === 'function') renderNetflixDownloadsTab();
  if (typeof renderMcLibraryLessons === 'function') renderMcLibraryLessons();
    if (typeof renderHomePodcastReel === 'function') renderHomePodcastReel();
}

// ==========================================
// VIDEO PLAYBACK RESUME & PROGRESS TRACKING
// ==========================================

function getStoredPlaybackProgress() {
  try {
    const raw = localStorage.getItem('tpp_playback_progress');
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return { lastWatchedEpisode: 1, episodes: {} };
}

function getEpisodeProgress(modId) {
  const data = getStoredPlaybackProgress();
  return (data.episodes && data.episodes[modId]) ? data.episodes[modId] : null;
}

function formatCinemaTime(sec) {
  if (!sec || isNaN(sec) || sec < 0) return '00:00';
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function saveVideoProgress(modId, currentTime, duration) {
  if (!modId || typeof currentTime !== 'number' || currentTime < 1) return;
  const mod = MODULES.find(m => m.id === modId);
  const dur = (duration && duration > 0) ? duration : ((mod && mod.dur) ? mod.dur * 60 : 720);
  const pct = Math.min(100, Math.max(0, Math.round((currentTime / dur) * 100)));
  const isComplete = pct >= 92;

  try {
    const data = getStoredPlaybackProgress();
    if (!data.episodes) data.episodes = {};
    data.lastWatchedEpisode = modId;
    data.episodes[modId] = {
      currentTime: Math.round(currentTime * 10) / 10,
      duration: Math.round(dur),
      percent: pct,
      completed: isComplete,
      updatedAt: Date.now()
    };
    localStorage.setItem('tpp_playback_progress', JSON.stringify(data));
  } catch (e) {}

  // Update Cinema HUD
  const hudTime = document.getElementById('cinema-hud-time');
  const hudBar = document.getElementById('cinema-hud-progress-fill');
  if (hudTime) hudTime.textContent = `${formatCinemaTime(currentTime)} / ${formatCinemaTime(dur)}`;
  if (hudBar) hudBar.style.width = `${pct}%`;

  // Update Continue Watching card if on Home
  const contBar = document.getElementById('tpp-cont-progress-fill');
  const contPct = document.getElementById('tpp-cont-pct');
  if (contBar) contBar.style.width = `${pct}%`;
  if (contPct) contPct.textContent = `${pct}%`;
}

function showResumePill(resumeSeconds) {
  const pill = document.getElementById('cinema-resume-pill');
  const txt = document.getElementById('cinema-resume-pill-text');
  if (!pill) return;
  if (txt) {
    const isMy = (typeof lang !== 'undefined' ? lang : 'en') === 'my';
    txt.textContent = isMy ? `${formatCinemaTime(resumeSeconds)} မှ ပြန်လည်စတင်ပါသည်` : `Resumed at ${formatCinemaTime(resumeSeconds)}`;
  }
  pill.style.display = 'inline-flex';
  clearTimeout(pill._timer);
  pill._timer = setTimeout(() => {
    pill.style.display = 'none';
  }, 7000);
}

function hideResumePill() {
  const pill = document.getElementById('cinema-resume-pill');
  if (pill) pill.style.display = 'none';
}

function restartCinemaFromBeginning() {
  const video = document.getElementById('mobile-cinema-video');
  const iframe = document.getElementById('mobile-cinema-iframe');
  hideResumePill();

  if (video && video.style.display !== 'none') {
    video.currentTime = 0;
    video.play().catch(() => {});
  } else if (iframe && iframe.contentWindow) {
    iframe.contentWindow.postMessage(JSON.stringify({ event: 'command', func: 'seekTo', args: [0, true] }), '*');
    iframe.contentWindow.postMessage(JSON.stringify({ event: 'command', func: 'playVideo', args: '' }), '*');
  }

  saveVideoProgress(currentMobileModId, 0, 0);
  const isMy = (typeof lang !== 'undefined' ? lang : 'en') === 'my';
  showToast(isMy ? 'အစမှ ပြန်လည်ဖွင့်လှစ်ပါသည်' : 'Restarted from beginning');
}

function resumeLastWatchedVideo() {
  const data = getStoredPlaybackProgress();
  const lastId = data.lastWatchedEpisode || 1;
  openCinemaDirectly(lastId);
}

function seekCinemaByClick(event) {
  const bar = document.getElementById('cinema-hud-progress-bar');
  if (!bar) return;
  const rect = bar.getBoundingClientRect();
  const clickX = event.clientX - rect.left;
  const pct = Math.max(0, Math.min(1, clickX / rect.width));

  const video = document.getElementById('mobile-cinema-video');
  const iframe = document.getElementById('mobile-cinema-iframe');
  const mod = MODULES.find(m => m.id === currentMobileModId);
  const durSec = (video && video.duration) ? video.duration : ((mod && mod.dur) ? mod.dur * 60 : 720);
  const targetSec = pct * durSec;

  if (video && video.style.display !== 'none') {
    video.currentTime = targetSec;
  } else if (iframe && iframe.contentWindow) {
    iframe.contentWindow.postMessage(JSON.stringify({ event: 'command', func: 'seekTo', args: [Math.floor(targetSec), true] }), '*');
  }
  saveVideoProgress(currentMobileModId, targetSec, durSec);
}

function saveCurrentCinemaPosition() {
  const video = document.getElementById('mobile-cinema-video');
  if (video && video.style.display !== 'none' && video.currentTime > 0) {
    saveVideoProgress(currentMobileModId, video.currentTime, video.duration);
  }
}

function pauseCinemaPlayback() {
  const video = document.getElementById('mobile-cinema-video');
  const iframe = document.getElementById('mobile-cinema-iframe');
  if (video && video.style.display !== 'none') {
    try { video.pause(); } catch(e) {}
  } else if (iframe && iframe.contentWindow) {
    try { iframe.contentWindow.postMessage('{"event":"command","func":"pauseVideo","args":""}', '*'); } catch(e) {}
  }
}

function updateContinueWatchingCard(forceIsMy) {
  const isMy = forceIsMy !== undefined ? forceIsMy : ((typeof lang !== 'undefined' ? lang : 'en') === 'my');
  const card = document.getElementById('tpp-continue-card');
  const titleEl = document.getElementById('tpp-cont-title');
  const subEl = document.getElementById('tpp-cont-sub');
  const thumbEl = document.getElementById('tpp-cont-thumb');
  const barEl = document.getElementById('tpp-cont-progress-fill');
  const pctEl = document.getElementById('tpp-cont-pct');

  const data = getStoredPlaybackProgress();
  const lastId = data.lastWatchedEpisode || 1;
  const mod = MODULES.find(m => m.id === lastId) || MODULES[0];
  const epProg = (data.episodes && data.episodes[lastId]) ? data.episodes[lastId] : null;

  const title = isMy ? (mod.myTitle || mod.title) : mod.title;
  const durMin = mod.dur || 12;

  if (titleEl) titleEl.textContent = title;
  if (subEl) subEl.textContent = isMy ? `အပိုင်း ${mod.id} · ${durMin} မိနစ်` : `Episode ${mod.id} · ${durMin} min`;
  if (thumbEl) {
    const imgSrc = getModuleThumbB64(mod.id);
    if (imgSrc) {
      thumbEl.src = imgSrc;
    }
    thumbEl.alt = title;
  }

  const pct = epProg ? epProg.percent : 45;
  if (barEl) barEl.style.width = `${pct}%`;
  if (pctEl) pctEl.textContent = `${pct}%`;

  if (card) {
    card.onclick = () => openCinemaDirectly(mod.id);
  }
}

function setupVideoProgressTracking() {
  const video = document.getElementById('mobile-cinema-video');
  if (video) {
    video.addEventListener('timeupdate', () => {
      if (!video.paused && video.currentTime > 0) {
        saveVideoProgress(currentMobileModId, video.currentTime, video.duration);
      }
    });
    video.addEventListener('pause', () => {
      if (video.currentTime > 0) {
        saveVideoProgress(currentMobileModId, video.currentTime, video.duration);
      }
    });
    video.addEventListener('ended', () => {
      saveVideoProgress(currentMobileModId, video.duration || 1, video.duration || 1);
    });
  }

  // YouTube postMessage event listener
  window.addEventListener('message', (event) => {
    try {
      const data = typeof event.data === 'string' ? JSON.parse(event.data) : event.data;
      if (data && data.event === 'infoDelivery' && data.info) {
        const t = data.info.currentTime;
        const d = data.info.duration;
        if (typeof t === 'number' && t > 0) {
          saveVideoProgress(currentMobileModId, t, d || 0);
        }
      }
    } catch(e) {}
  });

  window.addEventListener('beforeunload', saveCurrentCinemaPosition);
  window.addEventListener('pagehide', saveCurrentCinemaPosition);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', setupVideoProgressTracking);
} else {
  setupVideoProgressTracking();
}

// Play from local blob if downloaded, else stream from R2 with automatic resume
async function playOfflineOrOnline(modId) {
  const mod = MODULES.find(m => m.id === modId);
  if (!mod) return;
  const iframe = document.getElementById('mobile-cinema-iframe');
  const video = document.getElementById('mobile-cinema-video');
  const isFile = mod.videoType === 'file' || (!mod.youtube && mod.fileUrl);

  // Check saved resume point
  const epProg = getEpisodeProgress(modId);
  const resumeSeconds = (epProg && epProg.currentTime > 4 && !epProg.completed) ? Math.floor(epProg.currentTime) : 0;

  if (isFile) {
    const offline = await getOfflineVideo(modId);
    if (iframe) { iframe.style.display = 'none'; iframe.src = ''; }
    if (video) {
      video.style.display = 'block';
      // Set poster/thumbnail so the first frame shows the module artwork
      video.poster = getVideoThumbSrc(mod);
      // Revoke previous blob URL if any
      if (video._blobUrl) { URL.revokeObjectURL(video._blobUrl); video._blobUrl = null; }
      if (offline) {
        const blobUrl = URL.createObjectURL(offline.blob);
        video._blobUrl = blobUrl;
        video.src = blobUrl;
        showOfflineBadge(true);
      } else {
        video.src = mod.fileUrl;
        showOfflineBadge(false);
      }
      video.load();

      // Resume position on metadata loaded
      if (resumeSeconds > 0) {
        const applyResume = () => {
          try {
            if (video.duration && resumeSeconds < video.duration - 5) {
              video.currentTime = resumeSeconds;
              showResumePill(resumeSeconds);
            }
          } catch(e) {}
        };
        video.addEventListener('loadedmetadata', applyResume, { once: true });
        video.addEventListener('canplay', applyResume, { once: true });
        if (video.readyState >= 1) applyResume();
      } else {
        hideResumePill();
      }

      video.play().catch(e => console.log('Autoplay deferred:', e));
    }
  } else {
    if (video) { video.pause(); video.src = ''; video.style.display = 'none'; }
    if (iframe) {
      iframe.style.display = 'block';
      if (resumeSeconds > 0) {
        iframe.src = `https://www.youtube.com/embed/${mod.youtube}?rel=0&enablejsapi=1&autoplay=1&start=${resumeSeconds}`;
        showResumePill(resumeSeconds);
      } else {
        iframe.src = `https://www.youtube.com/embed/${mod.youtube}?rel=0&enablejsapi=1&autoplay=1`;
        hideResumePill();
      }
    }
    showOfflineBadge(false);
  }
}

function showOfflineBadge(show) {
  let badge = document.getElementById('offline-playing-badge');
  if (!badge) return;
  badge.style.display = show ? 'flex' : 'none';
}

// UI: update the chip grid download icon state
function updateChipDownloadState(modId, state, pct) {
  // Update the small download btn next to the chip
  const btn = document.getElementById(`dl-btn-m${modId}`);
  if (btn) {
    if (state === 'downloading') {
      btn.innerHTML = `<span class="dl-icon dl-spinner"></span><span class="dl-pct">${pct}%</span>`;
      btn.title = `Downloading ${pct}%... (tap to cancel)`;
      btn.onclick = (e) => { e.stopPropagation(); cancelVideoDownload(modId); };
      btn.classList.add('downloading');
      btn.classList.remove('done');
    } else if (state === 'done') {
      btn.innerHTML = `<span class="dl-icon">⬇️</span>`;
      btn.title = 'Downloaded – available offline';
      btn.onclick = (e) => { e.stopPropagation(); showOfflineToast('✅ Already downloaded & available offline!', 'success'); };
      btn.classList.add('done');
      btn.classList.remove('downloading');
    } else {
      btn.innerHTML = `<span class="dl-icon">⬇</span>`;
      btn.title = 'Download for offline';
      btn.onclick = (e) => { e.stopPropagation(); openDownloadOptionsSheet(modId); };
      btn.classList.remove('done', 'downloading');
    }
  }
  updateCinemaDownloadButton(modId, state, pct);
}

function updateDownloadsPanelProgress(modId, pct, loaded, total) {
  const bar = document.getElementById(`dp-bar-${modId}`);
  const info = document.getElementById(`dp-info-${modId}`);
  if (bar) bar.style.width = pct + '%';
  if (info) info.textContent = `${formatFileSize(loaded)} / ${formatFileSize(total)} · ${pct}%`;
}

// ---- Dedicated Downloads Screen (Episode-by-Episode Management) ----
let currentDownloadsFilter = 'all';

function filterDownloadsList(filter) {
  currentDownloadsFilter = filter;
  ['all', 'saved', 'available'].forEach(f => {
    const btn = document.getElementById(`df-filter-${f}`);
    if (btn) btn.classList.toggle('active', f === filter);
  });
  renderDownloadsPage();
}

async function renderDownloadsPage() {
  const container = document.getElementById('downloads-episodes-list');
  const storagePill = document.getElementById('downloads-page-storage-badge');
  const heroStat = document.getElementById('downloads-hero-stat');
  if (!container) return;

  const allDownloaded = await getAllOfflineVideos();
  const downloadedMap = {};
  allDownloaded.forEach(v => { downloadedMap[v.modId] = v; });

  const activeIds = Object.keys(_activeDownloads).map(Number);
  const totalBytes = allDownloaded.reduce((s, v) => s + (v.meta?.size || 0), 0);

  // Update storage badges
  const storageText = formatFileSize(totalBytes) || '0 MB';
  if (storagePill) storagePill.textContent = `${storageText} Used`;
  if (heroStat) heroStat.textContent = `${allDownloaded.length} Episodes Saved · ${storageText} Used`;
  updateStorageMeter(totalBytes, allDownloaded.length);

  // Update bottom tab badge
  updateDownloadsTabBadge(allDownloaded.length + activeIds.length);

  const isMy = (typeof lang !== 'undefined' ? lang : 'my') === 'my';

  const cardsHtml = [];

  for (const mod of MODULES) {
    const isDownloaded = !!downloadedMap[mod.id];
    const isDownloading = !!_activeDownloads[mod.id];
    const downloadRec = downloadedMap[mod.id];

    // Filter check
    if (currentDownloadsFilter === 'saved' && !isDownloaded && !isDownloading) continue;
    if (currentDownloadsFilter === 'available' && isDownloaded) continue;

    const modTitle = isMy ? (mod.myTitle || mod.title) : mod.title;
    const sizeText = isDownloaded ? formatFileSize(downloadRec?.meta?.size) : '~55 MB';

    let actionSection = '';

    if (isDownloading) {
      const pct = _activeDownloads[mod.id].progress || 0;
      actionSection = `
        <div class="dl-episode-progress-wrap">
          <div class="dl-progress-bar-bg">
            <div class="dl-progress-bar-fill" id="dp-bar-${mod.id}" style="width:${pct}%"></div>
          </div>
          <div class="dl-progress-status-row">
            <span id="dp-info-${mod.id}" style="font-weight:700;color:#f0c355">Downloading... ${pct}%</span>
            <button type="button" class="btn-cancel-dl" onclick="cancelVideoDownload(${mod.id})">
              ✕ ${isMy ? 'ပယ်ဖျက်မည်' : 'Cancel'}
            </button>
          </div>
        </div>`;
    } else if (isDownloaded) {
      actionSection = `
        <button type="button" class="btn-watch-offline" onclick="watchOfflineEpisode(${mod.id})">
          ▶ ${isMy ? 'အော့ဖ်လိုင်း ကြည့်ရှုမည်' : 'Watch Offline'}
        </button>
        <button type="button" class="btn-delete-offline" onclick="deleteOfflineEpisode(${mod.id})" title="Delete video">
          🗑
        </button>`;
    } else {
      actionSection = `
        <button type="button" class="btn-dl-episode" onclick="startVideoDownload(${mod.id}, _downloadQuality || 'saver')">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M19 9h-4V3H9v6H5l7 7 7-7zM5 18v2h14v-2H5z"/></svg>
          <span>${isMy ? 'အပိုင်း ' + mod.id + ' ဒေါင်းလုဒ်ဆွဲမည်' : 'Download Episode ' + mod.id}</span>
          <span style="opacity:0.65;font-size:0.7rem;margin-left:4px">(${sizeText})</span>
        </button>`;
    }

    const cardClass = isDownloaded ? 'downloads-episode-card is-downloaded' : (isDownloading ? 'downloads-episode-card is-downloading' : 'downloads-episode-card');

    cardsHtml.push(`
      <div class="${cardClass}" id="dl-card-m${mod.id}">
        <div class="downloads-episode-top">
          <div class="downloads-episode-icon" style="background:${mod.grad || 'linear-gradient(135deg,#003087,#004ac2)'};overflow:hidden;position:relative;padding:0;">
            <img src="${getVideoThumbSrc(mod)}" alt="${modTitle}" style="width:100%;height:100%;object-fit:cover;display:block;position:relative;z-index:1;" onerror="this.style.display='none'"/>
            <span style="position:absolute;font-size:1.2rem;pointer-events:none;z-index:0;">${mod.icon || '🎬'}</span>
          </div>
          <div class="downloads-episode-info">
            <div class="downloads-episode-badge-row">
              <span class="downloads-episode-num">Episode ${mod.id} · ${mod.dur || '45'} mins</span>
              ${isDownloaded ? '<span class="downloads-offline-ready-tag">✓ Offline Ready</span>' : ''}
            </div>
            <div class="downloads-episode-title">${modTitle}</div>
            <div class="downloads-episode-meta">
              <span>${mod.scripture || ''}</span>
              ${isDownloaded ? `<span>· ${sizeText}</span>` : ''}
            </div>
          </div>
        </div>
        <div class="downloads-episode-bottom">
          ${actionSection}
        </div>
      </div>
    `);
  }

  if (cardsHtml.length === 0) {
    container.innerHTML = `
      <div style="text-align:center;padding:40px 20px;color:rgba(255,255,255,0.6)">
        <div style="font-size:2.5rem;margin-bottom:10px">📥</div>
        <div style="font-size:1rem;font-weight:700;color:#fff;margin-bottom:4px">
          ${currentDownloadsFilter === 'saved' ? 'စက်ထဲတွင် ဒေါင်းလုဒ်ရယူထားသော ဗီဒီယို မရှိသေးပါ' : 'ဒေါင်းလုဒ်ရယူရန် ဗီဒီယို မရှိပါ'}
        </div>
        <div style="font-size:0.75rem">
          ${currentDownloadsFilter === 'saved' ? 'မိမိကြည့်ရှုလိုသော အပိုင်းကို ရွေးချယ်၍ ဒေါင်းလုဒ်ဆွဲနိုင်ပါသည်' : ''}
        </div>
      </div>`;
    return;
  }

  container.innerHTML = cardsHtml.join('');
}

function watchOfflineEpisode(modId) {
  switchAppTab('cinema');
  selectMobileModuleVideo(modId, true);
  showOfflineToast(`▶ Playing Episode ${modId} from offline storage`, 'success');
}

async function deleteOfflineEpisode(modId) {
  await deleteOfflineVideo(modId);
  updateChipDownloadState(modId, 'none', 0);
  showOfflineToast(`🗑 Episode ${modId} deleted from device`, 'info');
  renderDownloadsPage();
}

function openDownloadsPanel() {
  switchAppTab('downloads');
}

function closeDownloadsPanel() {
  switchAppTab('cinema');
}

// Update the Downloads tab badge count
function updateDownloadsTabBadge(count) {
  let badge = document.getElementById('downloads-tab-badge');
  if (!badge) return;
  if (count > 0) {
    badge.textContent = count;
    badge.style.display = 'flex';
  } else {
    badge.style.display = 'none';
  }
}

// Toast notification
function showOfflineToast(msg, type = 'info') {
  let toast = document.getElementById('offline-toast');
  if (!toast) return;
  toast.textContent = msg;
  toast.className = `offline-toast offline-toast-${type} show`;
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => toast.classList.remove('show'), 3500);
}

// Init: refresh chip states on load
async function initOfflineManager() {
  const allSaved = await getAllOfflineVideos();
  for (const rec of allSaved) {
    updateChipDownloadState(rec.modId, 'done', 100);
  }
  updateDownloadsTabBadge(allSaved.length);
}

/* ========================================================
   FEATURE 1: NEXT-GEN OFFLINE DOWNLOADS & STORAGE METER
   ======================================================== */
let currentDownloadQuality = 'hd';
let smartDownloadEnabled = true;

function updateStorageMeter(totalBytes, count) {
  const ring = document.getElementById('dsm-svg-ring');
  const pctEl = document.getElementById('dsm-ring-pct');
  const vidSizeEl = document.getElementById('dsm-videos-size');
  const cacheSizeEl = document.getElementById('dsm-cache-size');
  const freeSizeEl = document.getElementById('dsm-free-size');
  
  const usedMB = (totalBytes || 0) / (1024 * 1024);
  const cacheMB = 4.2;
  const totalAppUsedMB = usedMB + cacheMB;
  const quotaMB = 1000;
  const pct = Math.min(100, Math.max(0, Math.round((totalAppUsedMB / quotaMB) * 100)));
  
  const circumference = 264;
  const dashoffset = circumference - (circumference * (pct / 100));

  if (ring) {
    ring.style.strokeDasharray = `${circumference}`;
    ring.style.strokeDashoffset = `${dashoffset}`;
  }
  if (pctEl) pctEl.textContent = `${pct}%`;
  if (vidSizeEl) vidSizeEl.textContent = formatFileSize(totalBytes) || '0 MB';
  if (cacheSizeEl) cacheSizeEl.textContent = `${cacheMB.toFixed(1)} MB`;
  if (freeSizeEl) {
    const freeGB = Math.max(2.4, (16 - (totalAppUsedMB / 1024))).toFixed(1);
    freeSizeEl.textContent = `~${freeGB} GB Free`;
  }
}

function setDownloadQuality(quality) {
  currentDownloadQuality = quality;
  try { localStorage.setItem('tpp_dl_quality', quality); } catch(e) {}
  ['hd', 'saver', 'audio'].forEach(q => {
    const el = document.getElementById(`ql-${q}`);
    if (el) el.classList.toggle('active', q === quality);
  });
  const names = { hd: 'HD 720p (~55 MB)', saver: 'Data Saver 480p (~25 MB)', audio: 'Audio Only (~8 MB)' };
  showOfflineToast(`⚡ Download Quality: ${names[quality]}`, 'info');
}

function toggleSmartDownload(checked) {
  smartDownloadEnabled = !!checked;
  try { localStorage.setItem('tpp_smart_dl', smartDownloadEnabled ? '1' : '0'); } catch(e) {}
  showOfflineToast(smartDownloadEnabled ? '✓ Smart Auto-Download ဖွင့်ထားပါသည်' : 'Smart Auto-Download ပိတ်လိုက်ပါသည်', 'info');
}

async function confirmDeleteAllDownloads() {
  const allDownloaded = await getAllOfflineVideos();
  if (allDownloaded.length === 0) {
    showOfflineToast('ရှင်းလင်းရန် အော့ဖ်လိုင်း ဗီဒီယို မရှိပါ', 'info');
    return;
  }
  if (confirm(`ဒေါင်းလုဒ်လုပ်ထားသော မော်ဂျူး (${allDownloaded.length}) ခုစလုံးကို စက်ထဲမှ ဖျက်ပစ်ရန် သေချာပါသလား?`)) {
    await deleteAllOfflineVideos();
  }
}

async function deleteAllOfflineVideos() {
  try {
    const db = await openOfflineDB();
    const tx = db.transaction(OFFLINE_STORE, 'readwrite');
    tx.objectStore(OFFLINE_STORE).clear();
    tx.oncomplete = () => {
      for (let i = 1; i <= 11; i++) {
        updateChipDownloadState(i, 'none', 0);
      }
      showOfflineToast('🗑 ဒေါင်းလုဒ် ဗီဒီယိုအားလုံးကို အောင်မြင်စွာ ရှင်းလင်းပြီးပါပြီ', 'success');
      renderDownloadsPage();
    };
  } catch(e) {
    showOfflineToast('ရှင်းလင်းရာတွင် ချို့ယွင်းချက်ရှိပါသည်', 'error');
  }
}

